const LukitaBlockoutViewer = lazy(() => new Promise<typeof import("@/components/LukitaBlockoutViewer")>((resolve) => { const load = () => import("@/components/LukitaBlockoutViewer").then(resolve); if (typeof window === "undefined") load(); else window.setTimeout(load, 80); }));
type DeferredViewerProps = ComponentProps<typeof LukitaBlockoutViewer>;
function DeferredLukitaBlockoutViewer(props: DeferredViewerProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const [shouldLoad, setShouldLoad] = useState(false);
  useEffect(() => {
    const host = hostRef.current;
    if (!host || typeof window === "undefined") return;
    if (!("IntersectionObserver" in window)) { setShouldLoad(true); return; }
    const observer = new IntersectionObserver((entries) => { if (entries.some((entry) => entry.isIntersecting)) { setShouldLoad(true); observer.disconnect(); } }, { rootMargin: "480px" });
    observer.observe(host);
    return () => observer.disconnect();
  }, []);
  return <div ref={hostRef} className="h-full">{shouldLoad ? <Suspense fallback={<div className="grid h-full place-items-center bg-[#091a1e] text-xs text-slate-400">Preparando visor 3D…</div>}><LukitaBlockoutViewer {...props} /></Suspense> : <div className="grid h-full place-items-center bg-[#091a1e] text-xs text-slate-500">El visor 3D se cargará al acercarte.</div>}</div>;
}
